date, delta = date_and_delta(value, now=when)
if date is None:
    # Handle very large timedeltas or invalid inputs
    if isinstance(delta, str):
        return delta  # Already processed (e.g., "NaN")
    # Handle very large timedeltas that can't be converted to dates
    # Use days directly for large values
    days = abs(delta.days)
    years = days // 365
    remaining_days = days % 365

    if years > 0:
        result = ngettext("%d year", "%d years", years) % years
        if remaining_days > 0:
            months = int(remaining_days // 30.5)
            if months == 1:
                result += f", {months} month"
            else:
                result += f", {months} months"
        return result
    elif remaining_days > 0:
        months = int(remaining_days // 30.5)
        if months > 0:
            return ngettext("%d month", "%d months", months) % months
        return _("a day")
    return _("a moment")

